<template>
  <el-dialog
    title="分享设置"
    :visible.sync="dialogFormVisible"
    v-if="dialogFormVisible"
  >
    <el-form ref="shareSettingForm" :model="form" :inline="true">
      <el-form-item label="状态">
        <el-switch
          v-model="form.status"
          active-color="#13ce66"
          inactive-color="#ff4949"
          :active-value="1"
          :inactive-value="0"
        >
        </el-switch>
      </el-form-item>
      <el-form-item label="限时分享">
        <div>
          <el-switch
            v-model="form.time_limit"
            active-color="#13ce66"
            inactive-color="#ff4949"
            :active-value="1"
            :inactive-value="0"
            @change="onTimeLimitChange"
          >
          </el-switch>
        </div>
        <div class="el-upload__tip" style="width: 250px">
          限时分享链接与二维码是单独生成，分享后到期生效。原作品链接依旧有效.
        </div>
      </el-form-item>
      <el-form-item label="失效时间" :label-width="formLabelWidth">
        <el-select v-model="form.expired_time">
          <el-option
            v-for="item in expiredTimeOptions"
            :key="item.value"
            :label="item.label"
            :value="item.value"
          >
          </el-option>
        </el-select>
      </el-form-item>
      <el-form-item label="作品链接" :label-width="formLabelWidth">
        <el-tooltip
          class="item"
          effect="dark"
          :content="viewUrl"
          placement="top"
        >
          <el-input type="text" :value="viewUrl" readonly disabled>
            <el-button
              slot="append"
              icon="el-icon-copy-document"
              @click="copyToClipboard(shareUrl)"
            ></el-button>
          </el-input>
        </el-tooltip>
      </el-form-item>
      <el-form-item label="网站内嵌" :label-width="formLabelWidth">
        <el-tooltip
          class="item"
          effect="dark"
          :content="viewUrl"
          placement="top"
        >
          <el-input type="text" :value="iframeViewUrl" readonly disabled>
            <el-button
              slot="append"
              icon="el-icon-copy-document"
              @click="copyToClipboard(iframeViewUrl)"
            ></el-button>
          </el-input>
        </el-tooltip>
        <div class="el-upload__tip">
          如嵌入后显示异常，请在html页面的head里加入以下代码：
          <pre>
                <meta name="viewport" content="width=device-width, user-scalable=no, initial-scale=1.0, maximum-scale=1.0, minimum-scale=1.0" />
            </pre>
        </div>
      </el-form-item>
    </el-form>
    <div slot="footer" class="dialog-footer">
      <el-button @click="onCancel">取 消</el-button>
      <el-button type="primary" @click="onSave">确 定</el-button>
    </div>
  </el-dialog>
</template>
  
  <script>
// eslint-disable-next-line no-unused-vars
import { getProductConfig, setProductConfig, getShareUrl } from '@/api/vr'
const defaultForm = {
  status: 1,
  time_limit: 0,
  expired_time: 1,
}
export default {
  name: 'watermarkConfig',
  data() {
    return {
      dialogFormVisible: false,
      form: Object.assign({}, defaultForm),
      formLabelWidth: '120px',
      expiredTimeOptions: [
        {
          value: 0.5,
          label: '半小时',
        },
        {
          value: 1,
          label: '1小时',
        },
        {
          value: 3,
          label: '3小时',
        },
        {
          value: 24,
          label: '24小时',
        },
        {
          value: 72,
          label: '3天',
        },
      ],
      shareUrl: '',
    }
  },
  props: {
    productId: null,
    viewUrl: {
      type: String,
      default: '',
    },
  },
  computed: {
    iframeViewUrl() {
      return `<iframe src="${this.shareUrl}"  width="500" height="700" scrolling="no" frameborder="0"  marginheight="0" marginwidth="0" allowfullscreen="true" mozallowfullscreen="true" webkitallowfullscreen="true"></iframe>`
    },
  },
  created() {
    this.shareUrl = this.viewUrl
  },
  methods: {
    async init() {
      this.dialogFormVisible = true
      await this.getConfig()
      await this.getShareUrl()
    },
    async getConfig() {
      const config = await getProductConfig(this.productId, 'product_share')
      if (config) {
        this.form = config.val
      }
    },
    async onTimeLimitChange(val) {
      if (val) {
        await this.getShareUrl()
      } else {
        this.shareUrl = this.viewUrl
      }
    },
    async getShareUrl() {
      if (!this.form.time_limit) {
        return
      }
      const res = await getShareUrl(this.productId)
      if (res.url) {
        this.shareUrl = res.url
      }
    },
    onCancel() {
      this.form = Object.assign({}, defaultForm)
      this.$refs.shareSettingForm.resetFields()
      this.dialogFormVisible = false
    },
    onSave() {
      this.$refs.shareSettingForm.validate((valid) => {
        if (valid) {
          setProductConfig(this.productId, 'product_share', this.form).then(
            (data, message) => {
              console.log('data, message:', data, message)
              this.$message.success('设置成功')
              this.onCancel()
            }
          )
        } else {
          return false
        }
      })
    },
    copyToClipboard(inputValue) {
      // 创建一个新的 textarea 元素，设置其值为 el-input 的值
      const textarea = document.createElement('textarea')
      textarea.value = inputValue
      // 将 textarea 添加到 DOM 中
      document.body.appendChild(textarea)
      // 选择并复制 textarea 的值
      textarea.select()
      document.execCommand('copy')
      // 移除 textarea 元素
      document.body.removeChild(textarea)
      // 提示复制成功
      this.$message.success('已复制到剪贴板')
    },
  },
}
</script>
  <style lang="less" scoped>
</style>